#include <iostream>
#include <map>
#include <string>
#include <variant>

constexpr int IDC_NAME{101}, IDC_AGE{102}, IDC_NEWS{103};

struct Person
{
    std::string name{};
    int age{};
    bool newsletter{};
};

struct Error
{
    int control{};
    std::string message{};
};

std::variant<Person, Error> fromControls(const std::map<int, std::string>& controls)
{
    return Person{};
}

int main()
{
    std::map<int, std::string> controls{{IDC_NAME, "Ada"}, {IDC_AGE, "abc"}, {IDC_NEWS, "1"}};
    auto r{fromControls(controls)};
    std::cout << std::holds_alternative<Error>(r) << '\n';
}
